export const USDC='0x3600000000000000000000000000000000000000';
export const RPC='https://rpc.mainnet.arc.io';
export function units(hex, decimals){if(!/^0x[0-9a-f]+$/i.test(hex))throw Error('Invalid RPC amount');return Number(BigInt(hex))/10**decimals}
export function protocols(rows){return rows.filter(p=>Number.isFinite(p.chainTvls?.Arc)).map(p=>({name:p.name,slug:p.slug,category:p.category,tvl:p.chainTvls.Arc,overlap:['Risk Curators','Yield Aggregator','Yield'].includes(p.category)})).sort((a,b)=>b.tvl-a.tvl)}
export function series(rows){return rows.map(p=>({date:Number(p.date),value:p.totalCirculating?.peggedUSD})).filter(p=>Number.isFinite(p.value)).sort((a,b)=>a.date-b.date)}
export function change(a,b){return Number.isFinite(a)&&Number.isFinite(b)&&b!==0?(a-b)/b*100:null}
export async function json(url,body){const r=await fetch(url,{signal:AbortSignal.timeout(25000),...(body?{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{})});if(!r.ok)throw Error('Source returned HTTP '+r.status);return r.json()}
async function rpc(method,params=[]){const d=await json(RPC,{jsonrpc:'2.0',id:1,method,params});if(d.error)throw Error(d.error.message);if(d.result==null)throw Error('Empty RPC response');return d.result}
export async function supply(){if(Number(BigInt(await rpc('eth_chainId')))!==5042)throw Error('Wrong network');const block=await rpc('eth_blockNumber');const call=data=>rpc('eth_call',[{to:USDC,data},block]);let vals;for(let i=0;i<3;i++){try{vals=await Promise.all([call('0x18160ddd'),call('0x313ce567')]);break}catch(e){if(i===2)throw e;await new Promise(r=>setTimeout(r,600))}}const decimals=Number(BigInt(vals[1]));if(decimals!==6)throw Error('Unexpected USDC decimals');return {value:units(vals[0],decimals),block:Number(BigInt(block)),time:Date.now()}}
export async function vaults(){const d=await json('https://blue-api.morpho.org/graphql',{query:'{ vaultV2s(first: 100, where: {chainId_in: [5042]}) { items { address name asset { symbol } totalAssetsUsd } } }'});if(d.errors)throw Error(d.errors[0].message);return d.data.vaultV2s.items.filter(v=>Number.isFinite(v.totalAssetsUsd)).sort((a,b)=>b.totalAssetsUsd-a.totalAssetsUsd)}
